-- Pakistan: ES/DE/FR milestone translations for the 6 milestones in
-- migration 372. Hand-translated, not machine copy-paste.

-- pk-fmcg-pilot-2024
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-fmcg-pilot-2024', 'es', 'La SRO 28(I)/2024 lanza el primer proyecto piloto de facturación digital de la FBR, para el sector de bienes de consumo masivo', 'El 1 de febrero de 2024, la Junta Federal de Ingresos de Pakistán (FBR) emitió la SRO 28(I)/2024, que modificó las Normas del Impuesto sobre las Ventas de 2006 para exigir a los grandes fabricantes, importadores y distribuidores de bienes de consumo masivo (FMCG) la emisión de facturas electrónicas integradas en tiempo real con los sistemas de la FBR. Este fue el origen de lo que desde entonces se ha convertido en el mandato de Facturación Digital de la FBR para toda la economía, aunque en esta etapa el requisito se aplicaba solo a un sector estrecho y específico, no a la población general de contribuyentes registrados que las SRO posteriores incorporarían al alcance.', '["No se requiere ninguna acción para este hito histórico -- se incluye como contexto de las entradas siguientes", "Si es fabricante, importador o distribuidor de FMCG, confirme que su integración de facturación digital de esta fase piloto sigue funcionando correctamente bajo el marco actual"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-fmcg-pilot-2024', 'de', 'SRO 28(I)/2024 startet das erste digitale Rechnungspilotprojekt der FBR, für den FMCG-Sektor', 'Am 1. Februar 2024 erließ Pakistans Bundessteuerbehörde (Federal Board of Revenue, FBR) die SRO 28(I)/2024, mit der die Umsatzsteuervorschriften von 2006 geändert wurden, um große Hersteller, Importeure und Vertreiber von schnelldrehenden Konsumgütern (FMCG) zur Ausstellung elektronischer Rechnungen mit Echtzeit-Integration in die Systeme der FBR zu verpflichten. Dies war der Ursprung dessen, was sich seither zur gesamtwirtschaftlichen Digital-Invoicing-Pflicht der FBR entwickelt hat, wobei die Anforderung zu diesem Zeitpunkt nur für einen eng umgrenzten, bestimmten Sektor galt -- nicht für die allgemeine Population registrierter Steuerpflichtiger, die spätere SROs in den Anwendungsbereich brachten.', '["Für diesen historischen Meilenstein ist keine Handlung erforderlich -- er dient als Kontext für die folgenden Einträge", "Wenn Sie Hersteller, Importeur oder Vertreiber von FMCG sind, prüfen Sie, ob Ihre Digital-Invoicing-Integration aus dieser Pilotphase unter dem aktuellen Rahmenwerk noch korrekt funktioniert"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-fmcg-pilot-2024', 'fr', 'La SRO 28(I)/2024 lance le premier projet pilote de facturation numérique de la FBR, pour le secteur des biens de grande consommation', 'Le 1er février 2024, l''Autorité fédérale des recettes du Pakistan (FBR) a publié la SRO 28(I)/2024, modifiant les règles de la taxe sur les ventes de 2006 pour exiger des grands fabricants, importateurs et distributeurs de biens de grande consommation (FMCG) qu''ils émettent des factures électroniques intégrées en temps réel aux systèmes de la FBR. Ce fut l''origine de ce qui est devenu depuis l''obligation de facturation numérique de la FBR à l''échelle de toute l''économie, bien qu''à ce stade l''exigence ne s''appliquait qu''à un secteur restreint et spécifique, et non à l''ensemble des contribuables assujettis enregistrés que les SRO ultérieures ont fait entrer dans le champ d''application.', '["Aucune action n''est requise pour ce jalon historique -- il est fourni à titre de contexte pour les entrées suivantes", "Si vous êtes fabricant, importateur ou distributeur de FMCG, vérifiez que votre intégration de facturation numérique issue de cette phase pilote fonctionne toujours correctement sous le cadre actuel"]');

-- pk-digital-invoicing-framework-2025
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-digital-invoicing-framework-2025', 'es', 'La SRO 69(I)/2025 establece el marco central de licencias e integración del Capítulo XIV', 'Emitida el 29 de enero de 2025, la SRO 69(I)/2025 desarrolló el Capítulo XIV de las Normas del Impuesto sobre las Ventas de 2006 hasta convertirlo en la columna vertebral técnica y legal del sistema de facturación digital de Pakistán: normas de licencia para integradores privados, la opción de integrarse a través de PRAL (Pakistan Revenue Automation Limited) sin coste, y el detalle procedimental de la presentación de facturas en tiempo real y su validación por la FBR. Esta SRO es fundacional y procedimental -- construyó el mecanismo que las SRO posteriores utilizarían para incorporar poblaciones específicas de contribuyentes al alcance, pero no amplió por sí misma quién estaba legalmente obligado a emitir facturas digitales.', '["No se requiere ninguna acción para este hito histórico -- establece el marco técnico/legal sobre el que se apoyan las SRO posteriores que amplían el alcance (709, 1413, 1852)", "Si está evaluando opciones de integración, tenga en cuenta que esta SRO es donde se establecieron formalmente las vías de integrador licenciado y PRAL"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-digital-invoicing-framework-2025', 'de', 'SRO 69(I)/2025 schafft das zentrale Lizenzierungs- und Integrationsrahmenwerk nach Kapitel XIV', 'Die am 29. Januar 2025 erlassene SRO 69(I)/2025 baute Kapitel XIV der Umsatzsteuervorschriften von 2006 zum technischen und rechtlichen Rückgrat des pakistanischen Digital-Invoicing-Systems aus: Lizenzierungsregeln für private Integratoren, die Möglichkeit einer kostenlosen Integration über PRAL (Pakistan Revenue Automation Limited) sowie die verfahrenstechnischen Details der Echtzeit-Rechnungsübermittlung und FBR-Validierung. Diese SRO ist grundlegend und verfahrenstechnischer Natur -- sie schuf den Mechanismus, den spätere SROs nutzten, um bestimmte Steuerpflichtigen-Gruppen in den Anwendungsbereich zu bringen, erweiterte aber selbst nicht, wer rechtlich zur Ausstellung digitaler Rechnungen verpflichtet war.', '["Für diesen historischen Meilenstein ist keine Handlung erforderlich -- er schafft das technische/rechtliche Rahmenwerk, auf dem spätere anwendungsbereichserweiternde SROs (709, 1413, 1852) aufbauen", "Wenn Sie Integrationsoptionen prüfen, beachten Sie, dass mit dieser SRO die Wege über lizenzierte Integratoren und PRAL formell eingeführt wurden"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-digital-invoicing-framework-2025', 'fr', 'La SRO 69(I)/2025 établit le cadre central d''agrément et d''intégration du chapitre XIV', 'Publiée le 29 janvier 2025, la SRO 69(I)/2025 a développé le chapitre XIV des règles de la taxe sur les ventes de 2006 pour en faire l''ossature technique et juridique du système de facturation numérique du Pakistan : règles d''agrément pour les intégrateurs privés, possibilité de s''intégrer via PRAL (Pakistan Revenue Automation Limited) sans frais, et détail procédural de la soumission des factures en temps réel et de leur validation par la FBR. Cette SRO est fondatrice et procédurale -- elle a construit le mécanisme que les SRO ultérieures utiliseraient pour faire entrer des populations spécifiques de contribuables dans le champ d''application, mais elle n''a pas elle-même élargi qui était légalement tenu d''émettre des factures numériques.', '["Aucune action n''est requise pour ce jalon historique -- il établit le cadre technique/juridique sur lequel s''appuient les SRO ultérieures élargissant le champ d''application (709, 1413, 1852)", "Si vous évaluez des options d''intégration, notez que c''est cette SRO qui a formellement établi les voies de l''intégrateur agréé et de PRAL"]');

-- pk-corporate-wave-2025
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-corporate-wave-2025', 'es', 'La primera ola de facturación digital obligatoria entra en vigor bajo el calendario final de la SRO 1852(I)/2025', 'A partir del 1 de noviembre de 2025, bajo el calendario definitivo de la SRO 1852(I)/2025 (emitida el 24 de septiembre de 2025, tras la ampliación a entidades corporativas y no corporativas de la SRO 709(I)/2025 y dos prórrogas mensuales posteriores del plazo, y después del intento de escalonamiento por volumen de negocio de la SRO 1413(I)/2025), la primera ola de personas registradas quedó legalmente obligada a integrarse con el sistema de Facturación Digital de la FBR: sociedades cotizadas, importadores, empresas con un volumen de negocio superior a 1.000 millones de rupias, y proveedores del gobierno (B2G). Bajo el mismo calendario siguieron nuevas olas el 15 de noviembre y el 1 de diciembre de 2025, antes de la fecha del 31 de diciembre de 2025 que incorpora a todos los demás.', '["Si su empresa es una sociedad cotizada, un importador, tiene un volumen de negocio superior a 1.000 millones de rupias, o suministra a entidades gubernamentales, confirme que su integración con la Facturación Digital de la FBR estuvo activa desde esta fecha", "Elija ahora una vía de integración -- conexión API directa, un integrador licenciado, o la opción gratuita de PRAL -- en lugar de esperar al plazo de una ola posterior"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-corporate-wave-2025', 'de', 'Erste Welle der verpflichtenden digitalen Rechnungsstellung startet nach dem endgültigen Zeitplan der SRO 1852(I)/2025', 'Ab dem 1. November 2025 wurde nach dem maßgeblichen Zeitplan der SRO 1852(I)/2025 (erlassen am 24. September 2025, nach der Ausweitung auf körperschaftliche und nicht-körperschaftliche Steuerpflichtige durch die SRO 709(I)/2025 und zwei nachfolgenden einmonatigen Fristverlängerungen, sowie dem nach Umsatz gestaffelten Versuch der SRO 1413(I)/2025) die erste Welle registrierter Personen rechtlich zur Integration in das Digital-Invoicing-System der FBR verpflichtet: börsennotierte Aktiengesellschaften, Importeure, Unternehmen mit einem Umsatz über 1 Milliarde Rupien sowie Lieferanten an die öffentliche Hand (B2G). Nach demselben Zeitplan folgten weitere Wellen am 15. November und 1. Dezember 2025, vor dem Datum 31. Dezember 2025, das alle übrigen erfasst.', '["Wenn Ihr Unternehmen eine börsennotierte Aktiengesellschaft, ein Importeur ist, einen Umsatz über 1 Milliarde Rupien hat oder öffentliche Stellen beliefert, prüfen Sie, ob Ihre FBR-Digital-Invoicing-Integration ab diesem Datum aktiv war", "Wählen Sie jetzt einen Integrationsweg -- direkte API-Anbindung, ein lizenzierter Integrator oder die kostenlose PRAL-Option -- statt auf die Frist einer späteren Welle zu warten"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-corporate-wave-2025', 'fr', 'Première vague de facturation numérique obligatoire selon le calendrier définitif de la SRO 1852(I)/2025', 'À compter du 1er novembre 2025, selon le calendrier définitif de la SRO 1852(I)/2025 (publiée le 24 septembre 2025, après l''extension aux personnes morales et non morales de la SRO 709(I)/2025 et deux prorogations d''un mois de l''échéance, puis la tentative d''échelonnement par chiffre d''affaires de la SRO 1413(I)/2025), la première vague de personnes enregistrées a été légalement tenue de s''intégrer au système de facturation numérique de la FBR : sociétés cotées, importateurs, entreprises dont le chiffre d''affaires dépasse 1 milliard de roupies, et fournisseurs du gouvernement (B2G). D''autres vagues selon le même calendrier ont suivi les 15 novembre et 1er décembre 2025, avant la date du 31 décembre 2025 qui fait entrer tous les autres.', '["Si votre entreprise est une société cotée, un importateur, réalise un chiffre d''affaires supérieur à 1 milliard de roupies, ou fournit des entités gouvernementales, vérifiez que votre intégration à la facturation numérique de la FBR était active à compter de cette date", "Choisissez dès maintenant une voie d''intégration -- connexion API directe, intégrateur agréé, ou option gratuite de PRAL -- plutôt que d''attendre l''échéance d''une vague ultérieure"]');

-- pk-full-rollout-2025
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-full-rollout-2025', 'es', 'Todas las personas registradas restantes deben integrarse -- se completa el despliegue formal por fases', 'A partir del 31 de diciembre de 2025, la última ola de la SRO 1852(I)/2025 incorporó al alcance a toda persona registrada a efectos del impuesto sobre las ventas que quedaba fuera, completando sobre el papel el despliegue por fases que había comenzado con el proyecto piloto de FMCG de la SRO 28(I)/2024 casi dos años antes. En la práctica, el cumplimiento real en vivo se quedó muy por detrás de este plazo legal: el propio Miembro para la Transformación Estratégica de la FBR declaró que solo alrededor de un tercio de los contribuyentes registrados emitía facturas digitales en vivo a finales de marzo de 2026, e incluso según la métrica más antigua y estrecha de los puntos de venta (POS) de Nivel 1, entre el 27% y el 32% de las aproximadamente 37.000 sucursales minoristas integradas seguían desconectadas en junio de 2026. La FBR solo comenzó una aplicación seria -- procedimientos sancionadores a importadores, suspensión de registro, retirada del canal verde aduanero -- a partir del 1 de julio de 2026, con el objetivo de lograr la adopción plena para el 31 de julio de 2026. Según la investigación más reciente (5 de agosto de 2026), no existe confirmación en ningún sentido de si ese objetivo se cumplió realmente -- trate este hito como la finalización legal del mandato, no como prueba de que el cumplimiento esté completo en la práctica.', '["No asuma que el plazo del 31 de diciembre de 2025 significa que el mandato está resuelto en la práctica -- los propios datos de la FBR muestran que el cumplimiento real aún se está poniendo al día a mediados de 2026", "Si todavía no se ha integrado, trate la presión de aplicación de la FBR posterior al 1 de julio de 2026 (procedimientos sancionadores, suspensión de registro, retirada del canal verde) como un riesgo activo, no como una posibilidad futura"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-full-rollout-2025', 'de', 'Alle übrigen registrierten Personen müssen sich integrieren -- der formale stufenweise Rollout wird abgeschlossen', 'Ab dem 31. Dezember 2025 brachte die letzte Welle der SRO 1852(I)/2025 jede verbleibende umsatzsteuerlich registrierte Person in den Anwendungsbereich und schloss damit auf dem Papier den stufenweisen Rollout ab, der fast zwei Jahre zuvor mit dem FMCG-Pilotprojekt der SRO 28(I)/2024 begonnen hatte. In der Praxis lag die tatsächliche Live-Einhaltung deutlich hinter dieser rechtlichen Frist zurück: Das für strategische Transformation zuständige Mitglied der FBR erklärte selbst, dass Ende März 2026 nur rund ein Drittel der registrierten Steuerpflichtigen tatsächlich Live-Digitalrechnungen ausstellte, und selbst nach der älteren, engeren Tier-1-POS-Kennzahl waren im Juni 2026 noch 27-32 % der rund 37.000 integrierten Einzelhandelsfilialen nicht angeschlossen. Die FBR begann erst ab dem 1. Juli 2026 mit ernsthafter Durchsetzung -- Bußgeldverfahren gegen Importeure, Aussetzung der Registrierung, Entzug des Zoll-Grünkanals -- mit dem Ziel, bis zum 31. Juli 2026 volle Compliance zu erreichen. Nach dem Stand der jüngsten Recherche (5. August 2026) gibt es keine Bestätigung in die eine oder andere Richtung, ob dieses Ziel tatsächlich erreicht wurde -- betrachten Sie diesen Meilenstein als den rechtlichen Abschluss der Pflicht, nicht als Beleg dafür, dass die Einhaltung in der Praxis vollständig ist.', '["Gehen Sie nicht davon aus, dass die Frist vom 31. Dezember 2025 bedeutet, dass die Pflicht in der Praxis erledigt ist -- die eigenen Daten der FBR zeigen, dass die tatsächliche Einhaltung Mitte 2026 noch aufholt", "Wenn Sie sich noch nicht integriert haben, behandeln Sie den Durchsetzungsdruck der FBR nach dem 1. Juli 2026 (Bußgeldverfahren, Aussetzung der Registrierung, Entzug des Grünkanals) als aktives Risiko, nicht als zukünftige Möglichkeit"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-full-rollout-2025', 'fr', 'Toutes les personnes enregistrées restantes doivent s''intégrer -- le déploiement formel par phases s''achève', 'À compter du 31 décembre 2025, la dernière vague de la SRO 1852(I)/2025 a fait entrer dans le champ d''application toute personne enregistrée à la taxe sur les ventes encore hors périmètre, achevant sur le papier le déploiement par phases entamé près de deux ans plus tôt avec le projet pilote FMCG de la SRO 28(I)/2024. Dans la pratique, la conformité réelle sur le terrain a considérablement pris du retard par rapport à cette échéance légale : le membre de la FBR chargé de la transformation stratégique a lui-même déclaré que seul environ un tiers des contribuables enregistrés émettait des factures numériques en direct fin mars 2026, et même selon l''indicateur plus ancien et plus restreint des points de vente (POS) de niveau 1, 27 à 32 % des quelque 37 000 succursales de détail intégrées restaient déconnectées en juin 2026. La FBR n''a engagé une application sérieuse -- procédures de sanction contre les importateurs, suspension d''enregistrement, retrait du canal vert douanier -- qu''à compter du 1er juillet 2026, visant une adoption complète pour le 31 juillet 2026. À la date des recherches les plus récentes (5 août 2026), rien ne confirme dans un sens ou dans l''autre si cet objectif a réellement été atteint -- considérez ce jalon comme l''achèvement légal de l''obligation, et non comme la preuve que la conformité est complète dans la pratique.', '["Ne présumez pas que l''échéance du 31 décembre 2025 signifie que l''obligation est réglée dans la pratique -- les propres données de la FBR montrent que la conformité réelle est encore en train de rattraper son retard mi-2026", "Si vous ne vous êtes pas encore intégré, considérez la pression d''application de la FBR après le 1er juillet 2026 (procédures de sanction, suspension d''enregistrement, retrait du canal vert) comme un risque actif, non comme une possibilité future"]');

-- pk-service-sector-draft-2026
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-service-sector-draft-2026', 'es', 'El proyecto de SRO 288(I)/2026 propone extender la facturación en tiempo real a una amplia nueva población del sector servicios', 'Publicado el 18 de febrero de 2026 en el marco del Capítulo VIIA de las Normas del Impuesto sobre la Renta, el proyecto de SRO 288(I)/2026 extendería las obligaciones de facturación en tiempo real a una amplia nueva población de empresas del sector servicios -- restaurantes, hospitales, salones de belleza, empresas de mensajería, contadores, escuelas, gimnasios y otros. El documento primario de la FBR confirma que se publicó como un borrador sujeto a un periodo de consulta pública de 7 días, y requiere una orden general del impuesto sobre la renta adicional antes de poder entrar realmente en vigor. Parte de la prensa pakistaní (Business Recorder, ProPakistani) lo describió en febrero de 2026 como si ya fuera un mandato vinculante -- ese enfoque se adelanta al estatus legal real. Trátelo como una expansión pendiente y prevista, no confirmada, hasta que la FBR publique la orden general de seguimiento.', '["Si su empresa entra en alguna de las categorías recién propuestas (restaurante, hospital, salón de belleza, mensajería, firma contable, escuela, gimnasio, etc.), empiece a prepararse, pero no trate la SRO 288(I)/2026 como ya legalmente vinculante", "Esté atento a la orden general del impuesto sobre la renta de seguimiento que realmente pondría en vigor este proyecto -- es ese documento el que hay que seguir, no el proyecto de SRO en sí"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-service-sector-draft-2026', 'de', 'Entwurf der SRO 288(I)/2026 schlägt die Ausweitung der Echtzeit-Rechnungsstellung auf eine breite neue Dienstleistungssektor-Population vor', 'Der am 18. Februar 2026 unter Kapitel VIIA der Einkommensteuervorschriften veröffentlichte Entwurf der SRO 288(I)/2026 würde die Pflicht zur Echtzeit-Rechnungsstellung auf eine breite neue Gruppe von Dienstleistungsunternehmen ausweiten -- Restaurants, Krankenhäuser, Salons, Kurierdienste, Buchhalter, Schulen, Fitnessstudios und mehr. Das primäre FBR-Dokument bestätigt, dass dies als Entwurf für eine 7-tägige öffentliche Konsultationsfrist veröffentlicht wurde, und es bedarf eines weiteren Einkommensteuer-Generalerlasses, bevor es tatsächlich in Kraft treten kann. Ein Teil der pakistanischen Presse (Business Recorder, ProPakistani) beschrieb es im Februar 2026, als handele es sich bereits um eine verbindliche Pflicht -- diese Darstellung greift dem tatsächlichen rechtlichen Status vor. Behandeln Sie dies als eine anstehende, erwartete Erweiterung, nicht als bestätigte, bis die FBR den Folge-Generalerlass veröffentlicht.', '["Wenn Ihr Unternehmen in eine der neu vorgeschlagenen Kategorien fällt (Restaurant, Krankenhaus, Salon, Kurierdienst, Steuerberatungsfirma, Schule, Fitnessstudio usw.), beginnen Sie mit den Vorbereitungen, behandeln Sie die SRO 288(I)/2026 aber nicht als bereits rechtsverbindlich", "Achten Sie auf den folgenden Einkommensteuer-Generalerlass, der diesen Entwurf tatsächlich in Kraft setzen würde -- dieses Dokument sollten Sie verfolgen, nicht die Entwurfs-SRO selbst"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-service-sector-draft-2026', 'fr', 'Le projet de SRO 288(I)/2026 propose d''étendre la facturation en temps réel à une large nouvelle population du secteur des services', 'Publié le 18 février 2026 dans le cadre du chapitre VIIA des règles de l''impôt sur le revenu, le projet de SRO 288(I)/2026 étendrait les obligations de facturation en temps réel à une large nouvelle population d''entreprises du secteur des services -- restaurants, hôpitaux, salons, entreprises de messagerie, comptables, écoles, salles de sport, et bien d''autres. Le document primaire de la FBR confirme qu''il a été publié en tant que projet soumis à une période de consultation publique de 7 jours, et qu''il nécessite un arrêté général de l''impôt sur le revenu supplémentaire avant de pouvoir réellement entrer en vigueur. Une partie de la presse pakistanaise (Business Recorder, ProPakistani) l''a décrit en février 2026 comme s''il s''agissait déjà d''une obligation contraignante -- ce cadrage devance le statut juridique réel. Considérez-le comme une extension en attente et prévue, non confirmée, jusqu''à ce que la FBR publie l''arrêté général de suivi.', '["Si votre entreprise relève de l''une des catégories nouvellement proposées (restaurant, hôpital, salon, messagerie, cabinet comptable, école, salle de sport, etc.), commencez à vous préparer, mais ne traitez pas la SRO 288(I)/2026 comme déjà juridiquement contraignante", "Surveillez l''arrêté général de l''impôt sur le revenu à venir qui ferait réellement entrer ce projet en vigueur -- c''est ce document qu''il faut suivre, pas le projet de SRO lui-même"]');

-- pk-finance-bill-enforcement-2026
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-finance-bill-enforcement-2026', 'es', 'La Ley de Finanzas de 2026 endurece las sanciones de facturación electrónica y crea nueva infraestructura de aplicación', 'Presentada el 12 de junio de 2026 como parte de un paquete de reformas vinculado al FMI, la Ley de Finanzas de 2026 refuerza el marco sancionador que respalda el mandato de facturación digital de Pakistán en lugar de ampliar a quién se aplica: establece un Centro Nacional sin Rostro para realizar auditorías electrónicas del impuesto sobre las ventas, crea un registro público que nombra a los emisores de facturas falsas o "voladoras", y extiende las obligaciones de facturación electrónica a los bienes sujetos a impuestos especiales. Se trata de infraestructura de aplicación e integridad superpuesta al alcance ya existente del mandato, no de una nueva población que se incorpora por primera vez a la facturación digital.', '["Revise los cambios sancionadores de la Ley de Finanzas de 2026 aunque su empresa ya se haya integrado -- los mecanismos de aplicación (Centro sin Rostro, registro de facturas falsas) se suman a las obligaciones existentes", "Si su empresa comercia con bienes sujetos a impuestos especiales, confirme que su cobertura de facturación digital ahora se extiende a esas transacciones"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-finance-bill-enforcement-2026', 'de', 'Das Finanzgesetz 2026 verschärft die E-Rechnungs-Strafen und schafft neue Durchsetzungsinfrastruktur', 'Am 12. Juni 2026 als Teil eines IWF-verknüpften Reformpakets vorgelegt, stärkt das Finanzgesetz 2026 das Sanktionsrahmenwerk hinter Pakistans Digital-Invoicing-Pflicht, statt deren Anwendungsbereich zu erweitern: Es richtet ein Nationales Gesichtsloses Zentrum für elektronische Umsatzsteuerprüfungen ein, schafft ein öffentliches Register, das Aussteller gefälschter oder "fliegender" Rechnungen benennt, und weitet die E-Rechnungspflicht auf verbrauchsteuerpflichtige Waren aus. Dies ist Durchsetzungs- und Integritätsinfrastruktur, die auf den bereits bestehenden Anwendungsbereich der Pflicht aufgesetzt wird, keine neue Population, die erstmals in die digitale Rechnungsstellung einbezogen wird.', '["Prüfen Sie die Strafänderungen des Finanzgesetzes 2026, auch wenn Ihr Unternehmen bereits integriert ist -- die Durchsetzungsmechanismen (Gesichtsloses Zentrum, Register gefälschter Rechnungen) gelten zusätzlich zu bestehenden Pflichten", "Wenn Ihr Unternehmen mit verbrauchsteuerpflichtigen Waren handelt, prüfen Sie, ob Ihre Digital-Invoicing-Abdeckung nun auch diese Transaktionen umfasst"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pk-finance-bill-enforcement-2026', 'fr', 'La loi de finances 2026 durcit les sanctions relatives à la facturation électronique et bâtit une nouvelle infrastructure de contrôle', 'Présentée le 12 juin 2026 dans le cadre d''un train de réformes lié au FMI, la loi de finances 2026 renforce le cadre de sanctions qui soutient l''obligation de facturation numérique du Pakistan plutôt que d''en élargir le champ d''application : elle crée un Centre national sans visage pour mener des audits électroniques de la taxe sur les ventes, met en place un registre public nommant les émetteurs de fausses factures ou de factures « volantes », et étend les obligations de facturation électronique aux biens soumis à accise. Il s''agit d''une infrastructure de contrôle et d''intégrité superposée au champ d''application déjà existant de l''obligation, et non d''une nouvelle population entrant pour la première fois dans le périmètre de la facturation numérique.', '["Examinez les changements de sanctions de la loi de finances 2026 même si votre entreprise est déjà intégrée -- les mécanismes de contrôle (Centre sans visage, registre des fausses factures) s''appliquent en plus des obligations existantes", "Si votre entreprise traite des biens soumis à accise, vérifiez que votre couverture de facturation numérique s''étend désormais à ces transactions"]');
